 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    # The enclosing lines are the non-background color(s); flood the background
    # from the perimeter, then color any enclosed background component.
    outside = [[False] * w for _ in range(h)]
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == background and not outside[r][c]:
                outside[r][c] = True
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == background and not outside[r][c]:
                outside[r][c] = True
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and not outside[nr][nc] and grid[nr][nc] == background:
                outside[nr][nc] = True
                q.append((nr, nc))
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background and not outside[r][c]:
                out[r][c] = 4
    return out


def _check():
    demo = [
        [5,5,5,9,5,5,5,5,5,5,5,9,5,5,5],
        [5,5,5,9,5,5,5,5,5,5,5,9,5,5,5],
