        [9,5,5,5,5,5,9,5,5,5,9,9,9,9,9],
        [9,5,5,5,5,5,9,9,9,9,9,5,5,5,9],
        [9,5,5,5,5,5,9,5,5,5,9,9,9,9,9],
        [9,5,5,5,5,5,9,5,5,5,5,5,5,5,5],
        [9,9,9,9,9,9,9,5,5,5,5,5,5,5,5],
    ]
    expected = [row[:] for row in demo]
    for r in range(3, 7):
        for c in range(1, 6): expected[r][c] = 4
    for c in range(11, 14): expected[4][c] = 4
    assert transform(demo) == expected
    test = [[2]*10 for _ in range(23)]
    for r in range(23): test[r][7] = 8
    for r in (7, 10):
        for c in range(5, 10): test[r][c] = 8
    for r in (8, 9): test[r][5] = test[r][9] = 8
    result = transform(test)
    assert all(result[r][c] == 4 for r in (8,9) for c in (6,7,8))
    assert result[0][7] == 8 and result[8][5] == 8
    print('demo and test checks passed; test interior:', [[result[r][c] for c in range(5,10)] for r in range(7,11)])

if __name__ == '__main__':
    _check()
